j:jelly.script:
      function configureDataSourceRequestAction(referenceColumn) {
	   	var actionSysId = g_form.getValue(referenceColumn);
	   	var url = "/$flow-designer.do?sysparm_nostack=true#/action-designer/";
	  	 if (actionSysId)
	   		url = url + actionSysId + "/var/input";
    	else
       		url = url + "new/datasource_request";

	  	 var window = getTopWindow();
	     window.open(url);
      }
